class AssessmentSystem:
    FAIL_THRESHOLD = 60

    def __init__(self):
        self._students = {}

    @property
    def students(self):
        return self._students

    @students.setter
    def students(self, value):
        self._students = value

    def add_student(self, name, grade, major):
        self.students[name] = self._create_student_record(name, grade, major)

    def _create_student_record(self, name, grade, major):
        return {'name': name, 'grade': grade, 'major': major, 'courses': {}}

    def add_course_score(self, name, course, score):
        student = self._get_student(name)
        if student is not None:
            student['courses'][course] = score

    def _get_student(self, name):
        return self.students.get(name)

    def get_gpa(self, name):
        student = self._get_student(name)
        if student is None:
            return None
        courses = self._get_courses(student)
        if not courses:
            return None
        return self._calculate_average(courses.values())

    def _get_courses(self, student):
        return student['courses']

    def _calculate_average(self, values):
        values_list = list(values)
        count = len(values_list)
        if count == 0:
            return None
        return sum(values_list) / count

    def get_all_students_with_fail_course(self):
        return [
            name for name, student in self.students.items()
            if self._has_failed_course(student)
        ]

    def _has_failed_course(self, student):
        return any(score < self.FAIL_THRESHOLD for score in student['courses'].values())

    def get_course_average(self, course):
        scores = self._get_course_scores(course)
        return self._calculate_average(scores)

    def _get_course_scores(self, course):
        return [
            student['courses'][course]
            for student in self.students.values()
            if course in student['courses'] and student['courses'][course] is not None
        ]

    def get_top_student(self):
        top_student = None
        top_gpa = 0
        for name in self.students:
            gpa = self.get_gpa(name)
            if self._is_better_gpa(gpa, top_gpa):
                top_student = name
                top_gpa = gpa
        return top_student

    def _is_better_gpa(self, gpa, top_gpa):
        return gpa is not None and gpa > top_gpa
